import React, { useState, useEffect, useCallback } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { supabase } from '../../supabaseClient';
import { Calendar, Clock, ArrowLeft, Tag, Share2 } from 'lucide-react';
import { Helmet } from 'react-helmet-async';
import PublicLayout from '../layout/PublicLayout';
import './BlogPost.css';

function BlogPost() {
  const { slug } = useParams();
  const navigate = useNavigate();
  const [post, setPost] = useState(null);
  const [relatedPosts, setRelatedPosts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadPost();
    window.scrollTo(0, 0);
  }, [loadPost]);

  const loadPost = useCallback(async () => {
    try {
      setLoading(true);

      const { data, error } = await supabase
        .from('blog_posts')
        .select(`
          *,
          author:profiles(full_name, profile_photo),
          blog_post_categories(
            category:blog_categories(id, name, slug)
          ),
          blog_post_tags(
            tag:blog_tags(id, name, slug)
          )
        `)
        .eq('slug', slug)
        .eq('status', 'published')
        .single();

      if (error) throw error;

      setPost(data);

      // Increment view count
      await supabase.rpc('increment', {
        row_id: data.id,
        table_name: 'blog_posts',
        column_name: 'views_count'
      }).catch(() => {
        // Fallback if RPC doesn't exist
        supabase
          .from('blog_posts')
          .update({ views_count: (data.views_count || 0) + 1 })
          .eq('id', data.id);
      });

      // Load related posts (same category)
      if (data.blog_post_categories?.[0]?.category?.id) {
        const { data: related } = await supabase
          .from('blog_posts')
          .select(`
            *,
            blog_post_categories!inner(category_id)
          `)
          .eq('blog_post_categories.category_id', data.blog_post_categories[0].category.id)
          .eq('status', 'published')
          .neq('id', data.id)
          .limit(3);

        if (related) setRelatedPosts(related);
      }
    } catch (error) {
      console.error('Error loading post:', error);
    } finally {
      setLoading(false);
    }
  }, [slug]);

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  const handleShare = async () => {
    const url = window.location.href;
    if (navigator.share) {
      try {
        await navigator.share({
          title: post.title,
          text: post.excerpt || post.title,
          url: url
        });
      } catch (error) {
        // User cancelled or error
      }
    } else {
      // Fallback: copy to clipboard
      navigator.clipboard.writeText(url);
      alert('Link copied to clipboard!');
    }
  };

  if (loading) {
    return <div className="loading">Loading post...</div>;
  }

  if (!post) {
    return (
      <PublicLayout>
        <div className="error-state">
          <h2>Post not found</h2>
          <Link to="/blog" className="btn-primary">
            Back to Blog
          </Link>
        </div>
      </PublicLayout>
    );
  }

  const seoTitle = post.seo_title || post.title;
  const seoDescription = post.seo_description || post.excerpt || post.title;

  return (
    <PublicLayout>
      <Helmet>
        <title>{seoTitle} | 3dMatch Blog</title>
        <meta name="description" content={seoDescription} />
        {post.seo_keywords && <meta name="keywords" content={post.seo_keywords} />}
        <meta property="og:title" content={seoTitle} />
        <meta property="og:description" content={seoDescription} />
        {post.featured_image && <meta property="og:image" content={post.featured_image} />}
        <meta property="og:type" content="article" />
        <meta property="article:published_time" content={post.published_at} />
        <meta property="article:author" content={post.author?.full_name || 'Anonymous'} />
      </Helmet>

      <div className="blog-post-container">
        <button className="btn-back" onClick={() => navigate('/blog')}>
          <ArrowLeft size={20} />
          Back to Blog
        </button>

        <article className="blog-post">
          {/* Header */}
          <header className="post-header">
            <div className="post-meta-top">
              {post.blog_post_categories?.[0]?.category && (
                <Link
                  to={`/blog/category/${post.blog_post_categories[0].category.slug}`}
                  className="post-category"
                >
                  {post.blog_post_categories[0].category.name}
                </Link>
              )}
              <div className="post-meta-row">
                <span className="post-date">
                  <Calendar size={16} />
                  {formatDate(post.published_at)}
                </span>
                {post.reading_time && (
                  <span className="post-reading-time">
                    <Clock size={16} />
                    {post.reading_time} min read
                  </span>
                )}
              </div>
            </div>

            <h1 className="post-title">{post.title}</h1>

            {post.excerpt && (
              <p className="post-excerpt">{post.excerpt}</p>
            )}

            <div className="post-author-row">
              <div className="post-author">
                {post.author?.profile_photo && (
                  <img
                    src={post.author.profile_photo}
                    alt={post.author.full_name}
                    className="author-photo"
                  />
                )}
                <div>
                  <span className="author-label">Written by</span>
                  <span className="author-name">{post.author?.full_name || 'Anonymous'}</span>
                </div>
              </div>

              <button className="btn-share" onClick={handleShare}>
                <Share2 size={18} />
                Share
              </button>
            </div>
          </header>

          {/* Featured Image */}
          {post.featured_image && (
            <div className="post-featured-image">
              <img src={post.featured_image} alt={post.title} />
            </div>
          )}

          {/* Content */}
          <div
            className="post-content"
            dangerouslySetInnerHTML={{ __html: post.content }}
          />

          {/* Tags */}
          {post.blog_post_tags && post.blog_post_tags.length > 0 && (
            <div className="post-tags-section">
              <h3>Tags</h3>
              <div className="post-tags">
                {post.blog_post_tags.map((pt, index) => (
                  <Link
                    key={index}
                    to={`/blog/tag/${pt.tag.slug}`}
                    className="post-tag"
                  >
                    <Tag size={14} />
                    {pt.tag.name}
                  </Link>
                ))}
              </div>
            </div>
          )}
        </article>

        {/* Related Posts */}
        {relatedPosts.length > 0 && (
          <section className="related-posts-section">
            <h2 className="section-title">Related Articles</h2>
            <div className="related-posts-grid">
              {relatedPosts.map(relatedPost => (
                <Link
                  key={relatedPost.id}
                  to={`/blog/${relatedPost.slug}`}
                  className="related-post-card"
                >
                  {relatedPost.featured_image && (
                    <div className="related-post-image">
                      <img src={relatedPost.featured_image} alt={relatedPost.title} />
                    </div>
                  )}
                  <div className="related-post-content">
                    <h3>{relatedPost.title}</h3>
                    {relatedPost.excerpt && <p>{relatedPost.excerpt.substring(0, 100)}...</p>}
                  </div>
                </Link>
              ))}
            </div>
          </section>
        )}
      </div>
    </PublicLayout>
  );
}

export default BlogPost;
